CREATE DATABASE IF NOT EXISTS pvc_erp;
USE pvc_erp;

CREATE TABLE IF NOT EXISTS users (id VARCHAR(50) PRIMARY KEY, name VARCHAR(100), username VARCHAR(100), email VARCHAR(100) UNIQUE, password_hash VARCHAR(255), role_id VARCHAR(50), active BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS roles (id VARCHAR(50) PRIMARY KEY, name VARCHAR(50) UNIQUE);
CREATE TABLE IF NOT EXISTS permissions (id VARCHAR(50) PRIMARY KEY, name VARCHAR(100) UNIQUE, role_id VARCHAR(50));
CREATE TABLE IF NOT EXISTS buyers (id VARCHAR(50) PRIMARY KEY, name VARCHAR(100), contact VARCHAR(100), email VARCHAR(100), buyer_code VARCHAR(50), department VARCHAR(100), designation VARCHAR(100), spending_limit DECIMAL(12,2), active_orders_count INT, status VARCHAR(50), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS suppliers (id VARCHAR(50) PRIMARY KEY, name VARCHAR(100), phone_number VARCHAR(100), shop_address VARCHAR(255), company_name VARCHAR(100), supplier_code VARCHAR(50), category VARCHAR(100), contact_person VARCHAR(100), email VARCHAR(100), city VARCHAR(100), country VARCHAR(100), payment_terms VARCHAR(100), rating DECIMAL(3,1), status VARCHAR(50), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS purchases (id VARCHAR(50) PRIMARY KEY, po_number VARCHAR(100), supplier_id VARCHAR(50), supplier_name VARCHAR(100), buyer_id VARCHAR(50), buyer_name VARCHAR(100), purchase_date DATE, vehicle_number VARCHAR(255), material_type VARCHAR(100), color VARCHAR(100), grade VARCHAR(100), `condition` VARCHAR(100), store_id VARCHAR(50), gross_weight_kg DECIMAL(12,3), tare_weight_kg DECIMAL(12,3), net_weight_kg DECIMAL(12,3), rate_per_kg DECIMAL(12,2), total_amount DECIMAL(12,2), payment_type VARCHAR(50), paid_amount DECIMAL(12,2), payable_amount DECIMAL(12,2), status VARCHAR(50), currency VARCHAR(10) DEFAULT 'PKR', notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS store_locations (id VARCHAR(50) PRIMARY KEY, name VARCHAR(100), contact VARCHAR(100), address VARCHAR(255));
CREATE TABLE IF NOT EXISTS store_receipts (id VARCHAR(50) PRIMARY KEY, location_id VARCHAR(50), supplier_id VARCHAR(50), amount DECIMAL(12,2), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS store_transfers (id VARCHAR(50) PRIMARY KEY, from_loc VARCHAR(50), to_loc VARCHAR(50), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS stock (id VARCHAR(50) PRIMARY KEY, sku VARCHAR(100), qty INT, location_id VARCHAR(50));
CREATE TABLE IF NOT EXISTS adjustments (id VARCHAR(50) PRIMARY KEY, stock_id VARCHAR(50), delta INT, reason VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS stock_counts (id VARCHAR(50) PRIMARY KEY, location_id VARCHAR(50), counted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reports (id VARCHAR(50) PRIMARY KEY, title VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sorting (id VARCHAR(50) PRIMARY KEY, batch_no VARCHAR(100), qty INT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS washing (id VARCHAR(50) PRIMARY KEY, batch_no VARCHAR(100), qty INT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS production (id VARCHAR(50) PRIMARY KEY, batch_no VARCHAR(100), qty INT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sales (id VARCHAR(50) PRIMARY KEY, customer VARCHAR(100), amount DECIMAL(12,2), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sales_returns (id VARCHAR(50) PRIMARY KEY, sale_id VARCHAR(50), reason VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS costing (id VARCHAR(50) PRIMARY KEY, item VARCHAR(100), cost DECIMAL(12,2));
CREATE TABLE IF NOT EXISTS tax (id VARCHAR(50) PRIMARY KEY, name VARCHAR(100), rate DECIMAL(5,2));
